'use strict';

function uniqueBy(items, keyOf) {
  const seen = new Set();
  const result = [];
  for (const item of items) {
    const key = keyOf(item);
    if (seen.has(key)) continue;
    seen.add(key);
    result.push(item);
  }
  return result;
}

module.exports = { uniqueBy };

'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const { uniqueBy } = require('../src/solution.cjs');

test('keeps the first item for each duplicate key, in input order', () => {
  const items = [
    { id: 2, name: 'b1' },
    { id: 1, name: 'a1' },
    { id: 2, name: 'b2' },
    { id: 3, name: 'c1' },
    { id: 1, name: 'a2' },
  ];
  assert.deepEqual(uniqueBy(items, (x) => x.id), [
    { id: 2, name: 'b1' },
    { id: 1, name: 'a1' },
    { id: 3, name: 'c1' },
  ]);
});

test('returns every item when all keys are distinct', () => {
  const items = ['x', 'y', 'z'];
  assert.deepEqual(uniqueBy(items, (s) => s), ['x', 'y', 'z']);
});

test('treats number 1 and string "1" as different keys', () => {
  const items = [1, '1', 1, '1'];
  assert.deepEqual(uniqueBy(items, (x) => x), [1, '1']);
});

test('mixed key types: numeric and string keys with the same text stay separate', () => {
  const items = [
    { k: 1, v: 'num-1' },
    { k: '1', v: 'str-1' },
    { k: 0, v: 'num-0' },
    { k: '0', v: 'str-0' },
    { k: 1, v: 'num-1-dup' },
    { k: '0', v: 'str-0-dup' },
  ];
  assert.deepEqual(uniqueBy(items, (x) => x.k), [
    { k: 1, v: 'num-1' },
    { k: '1', v: 'str-1' },
    { k: 0, v: 'num-0' },
    { k: '0', v: 'str-0' },
  ]);
});

test('"__proto__" and other prototype-like names are ordinary keys', () => {
  const items = ['__proto__', 'constructor', '__proto__', 'toString', 'constructor'];
  assert.deepEqual(uniqueBy(items, (x) => x), ['__proto__', 'constructor', 'toString']);
});

test('empty input returns a new empty array', () => {
  const items = [];
  const result = uniqueBy(items, () => 'k');
  assert.deepEqual(result, []);
  assert.notEqual(result, items);
});

test('does not mutate the input array or its items', () => {
  const items = [{ id: 1 }, { id: 1 }, { id: 2 }];
  const snapshot = JSON.parse(JSON.stringify(items));
  const result = uniqueBy(items, (x) => x.id);
  assert.deepEqual(items, snapshot);
  assert.equal(items.length, 3);
  assert.notEqual(result, items);
  assert.equal(result[0], items[0]);
});

test('calls keyOf exactly once per item, in order', () => {
  const calls = [];
  uniqueBy(['a', 'b', 'a'], (x) => {
    calls.push(x);
    return x;
  });
  assert.deepEqual(calls, ['a', 'b', 'a']);
});

