    if not 1 <= port <= 65535:
        raise ValueError(f"port out of range: {text!r}")
    return port

_ASCII_DIGITS = frozenset("0123456789")
_MAX_PORT = 65535
_MAX_SIGNIFICANT_DIGITS = len(str(_MAX_PORT))


def parse_port(text):
    if not isinstance(text, str):
        raise ValueError(f"port must be a string, got {type(text).__name__}")

    body = text.strip(" ")
    if not body or any(ch not in _ASCII_DIGITS for ch in body):
        raise ValueError(f"invalid port: {text!r}")

    significant = body.lstrip("0")
    if not significant or len(significant) > _MAX_SIGNIFICANT_DIGITS:
        raise ValueError(f"port out of range: {text!r}")

    port = int(significant)
    if port > _MAX_PORT:
        raise ValueError(f"port out of range: {text!r}")
    return port

