    port = int(digits)
    if not 1 <= port <= 65535:
        raise ValueError(f"port out of range 1-65535: {text!r}")
    return port

def parse_port(text):
    if not isinstance(text, str):
        raise ValueError(f"port must be a str, not {type(text).__name__}")
    # Strip leading zeros before the length check so long zero-padded input is not rejected by int()'s digit limit.
    digits = text.strip(" ").lstrip("0")
    if not digits or len(digits) > 5 or not (digits.isascii() and digits.isdigit()):
        raise ValueError(f"invalid port: {text!r}")
    port = int(digits)
    if port > 65535:
        raise ValueError(f"port out of range: {text!r}")
    return port

MAX_PORT = 65535
_SPACE = " "


def parse_port(text):
    if not isinstance(text, str):
        raise ValueError("port must be a string")

    digits = text.strip(_SPACE)
    if not digits:
        raise ValueError("port must not be empty")

    value = 0
    for char in digits:
        if not "0" <= char <= "9":
            raise ValueError(f"invalid character in port: {char!r}")
        value = value * 10 + (ord(char) - ord("0"))
        if value > MAX_PORT:
            raise ValueError(f"port out of range: {text!r}")

    if value < 1:
        raise ValueError(f"port out of range: {text!r}")
    return value

