async function mapLimit(items, limit, fn) {
  if (!Number.isInteger(limit) || limit < 1) {
    throw new RangeError('limit must be a positive integer');
  }

  const list = Array.from(items);
  const results = new Array(list.length);
  let nextIndex = 0;
  let failed = false;

  async function worker() {
    while (!failed && nextIndex < list.length) {
      const index = nextIndex++;
      try {
        results[index] = await fn(list[index]);
      } catch (err) {
        failed = true;
        throw err;
      }
    }
  }

  const workerCount = Math.min(limit, list.length);
  const workers = [];
  for (let i = 0; i < workerCount; i++) {
    workers.push(worker());
  }

  await Promise.all(workers);
  return results;
}

module.exports = { mapLimit };

const { test } = require('node:test');
const assert = require('node:assert/strict');
const { mapLimit } = require('../src/solution.cjs');

function deferred() {
  let resolve;
  let reject;
  const promise = new Promise((res, rej) => {
    resolve = res;
    reject = rej;
  });
  return { promise, resolve, reject };
}

function controlled() {
  const calls = [];
  const fn = (item) => {
    const d = deferred();
    calls.push({ item, ...d });
    return d.promise;
  };
  return { calls, fn };
}

// Drains all pending microtasks so that any follow-up work has run.
function flush() {
  return new Promise((resolve) => setImmediate(resolve));
}

test('returns results in input order when calls finish out of order', async () => {
  const { calls, fn } = controlled();
  const result = mapLimit(['a', 'b', 'c'], 3, fn);
  await flush();
  assert.equal(calls.length, 3);

  calls[2].resolve('C');
  calls[1].resolve('B');
  calls[0].resolve('A');

  assert.deepEqual(await result, ['A', 'B', 'C']);
});

test('never has more than limit calls in flight', async () => {
  const { calls, fn } = controlled();
  const result = mapLimit([1, 2, 3, 4, 5], 2, fn);

  await flush();
  assert.deepEqual(calls.map((c) => c.item), [1, 2]);

  calls[1].resolve('b');
  await flush();
  assert.deepEqual(calls.map((c) => c.item), [1, 2, 3]);

  calls[0].resolve('a');
  await flush();
  assert.deepEqual(calls.map((c) => c.item), [1, 2, 3, 4]);

  calls[3].resolve('d');
  calls[2].resolve('c');
  await flush();
  assert.deepEqual(calls.map((c) => c.item), [1, 2, 3, 4, 5]);

  calls[4].resolve('e');
  assert.deepEqual(await result, ['a', 'b', 'c', 'd', 'e']);
});

