const { test } = require('node:test');
const assert = require('node:assert/strict');
const { retry } = require('../src/solution.cjs');

function fakeSleep() {
  const calls = [];
  const sleep = async (ms) => {
    calls.push(ms);
  };
  return { sleep, calls };
}

function failingThenSucceeding(failures, value) {
  let calls = 0;
  const operation = async () => {
    calls += 1;
    if (calls <= failures) {
      throw new Error(`fail ${calls}`);
    }
    return value;
  };
  return { operation, count: () => calls };
}

test('returns the first value without sleeping when the operation succeeds', async () => {
  const { sleep, calls } = fakeSleep();
  const op = failingThenSucceeding(0, 'ok');

  const result = await retry(op.operation, { attempts: 3, delayMs: 10, sleep, shouldRetry: () => true });

  assert.equal(result, 'ok');
  assert.equal(op.count(), 1);
  assert.deepEqual(calls, []);
});

test('retries rejected operations until one succeeds, sleeping delayMs between attempts', async () => {
  const { sleep, calls } = fakeSleep();
  const op = failingThenSucceeding(2, 'done');

  const result = await retry(op.operation, { attempts: 5, delayMs: 25, sleep, shouldRetry: () => true });

  assert.equal(result, 'done');
  assert.equal(op.count(), 3);
  assert.deepEqual(calls, [25, 25]);
});

test('throws the last error object unchanged after exhausting attempts', async () => {
  const { sleep, calls } = fakeSleep();
  const errors = [];
  let count = 0;
  const operation = async () => {
    count += 1;
    const error = new Error(`attempt ${count}`);
    errors.push(error);
    throw error;
  };

  await assert.rejects(
    retry(operation, { attempts: 3, delayMs: 7, sleep, shouldRetry: () => true }),
    (error) => error === errors[2],
  );

  assert.equal(count, 3);
  assert.deepEqual(calls, [7, 7]);
});

test('does not sleep after the final failed attempt', async () => {
  const { sleep, calls } = fakeSleep();
  const operation = async () => {
    throw new Error('nope');
  };

  await assert.rejects(retry(operation, { attempts: 1, delayMs: 50, sleep, shouldRetry: () => true }), /nope/);

  assert.deepEqual(calls, []);
});

test('stops immediately without sleeping when shouldRetry returns false', async () => {
  const { sleep, calls } = fakeSleep();
  const fatal = new Error('fatal');
  let count = 0;
  const operation = async () => {
    count += 1;
    throw fatal;
  };

  await assert.rejects(
    retry(operation, { attempts: 5, delayMs: 10, sleep, shouldRetry: () => false }),
    (error) => error === fatal,
  );

  assert.equal(count, 1);
  assert.deepEqual(calls, []);
});

test('passes the rejection reason to shouldRetry', async () => {
  const { sleep } = fakeSleep();
  const seen = [];
  const errors = [new Error('a'), new Error('b')];
  let count = 0;
  const operation = async () => {
    throw errors[count++];
  };

  await assert.rejects(
    retry(operation, {
      attempts: 2,
      delayMs: 0,
      sleep,
      shouldRetry: (error) => {
        seen.push(error);
        return true;
      },
    }),
    (error) => error === errors[1],
  );

  assert.deepEqual(seen, [errors[0]]);
});

test('waits for the sleep promise to resolve before the next attempt', async () => {
  let resolveSleep;
  const sleep = () => new Promise((resolve) => {
    resolveSleep = resolve;
  });
  const op = failingThenSucceeding(1, 'late');

  const pending = retry(op.operation, { attempts: 2, delayMs: 1, sleep, shouldRetry: () => true });
  await new Promise((resolve) => setImmediate(resolve));
  assert.equal(op.count(), 1);

  resolveSleep();
  assert.equal(await pending, 'late');
  assert.equal(op.count(), 2);
});

test('rejects invalid attempts with RangeError without calling the operation', async () => {
  for (const attempts of [0, -1, 1.5, NaN, Infinity, '2', undefined, null]) {
    let called = false;
    const operation = async () => {
      called = true;
    };

    await assert.rejects(
      retry(operation, { attempts, delayMs: 0, sleep: async () => {}, shouldRetry: () => true }),
      RangeError,
      `attempts=${String(attempts)}`,
    );
    assert.equal(called, false);
  }
});

from collections import deque


def topological_order(nodes, edges):
    indegree = {node: 0 for node in nodes}
    successors = {node: [] for node in nodes}
    for a, b in edges:
        successors[a].append(b)
        indegree[b] += 1

    queue = deque(node for node in nodes if indegree[node] == 0)
    order = []
    while queue:
        node = queue.popleft()
        order.append(node)
        for nxt in successors[node]:
            indegree[nxt] -= 1
            if indegree[nxt] == 0:
                queue.append(nxt)

    if len(order) != len(nodes):
        raise ValueError("graph contains a cycle")
    return order

