        self.assertEqual(self.names("al", 2), ["al", "alice"])

    def test_limit_clamped_to_at_least_one(self):
        self.assertEqual(len(search(self.conn, "", 0)), 1)
        self.assertEqual(len(search(self.conn, "", -5)), 1)

    def test_limit_clamped_to_at_most_100(self):
        self.conn.executemany(
            "INSERT INTO users VALUES (?, ?)",
            [(1000 + i, "bulk%03d" % i) for i in range(150)],
        )
        self.assertEqual(len(search(self.conn, "bulk", 500)), 100)

    def test_bool_limit_rejected(self):
        with self.assertRaises(ValueError):
            search(self.conn, "a", True)
        with self.assertRaises(ValueError):
            search(self.conn, "a", False)

    def test_non_integer_limits_rejected(self):
        for bad in (None, "5", 2.0, 1.5, [5]):
            with self.subTest(limit=bad):
                with self.assertRaises(ValueError):
                    search(self.conn, "a", bad)

    def test_non_string_prefix_rejected(self):
        with self.assertRaises(TypeError):
            search(self.conn, None, 5)


