import os
import sqlite3
import sys
import unittest

sys.path.insert(0, os.path.join(os.path.dirname(__file__), "..", "src"))

from solution import search


def make_db(rows):
    conn = sqlite3.connect(":memory:")
    conn.execute("CREATE TABLE users (id INTEGER, name TEXT)")
    conn.executemany("INSERT INTO users (id, name) VALUES (?, ?)", rows)
    return conn


def names(rows):
    return [name for _, name in rows]


class SearchTests(unittest.TestCase):
    def setUp(self):
        self.conn = make_db(
            [(1, "Ann"), (2, "Anne"), (3, "a%b"), (4, "a_b"),
             (5, "axb"), (6, "a\\b"), (7, "ab"), (8, "Bob")]
        )

    def test_plain_prefix_matches(self):
        self.assertEqual(names(search(self.conn, "An", 10)), ["Ann", "Anne"])

    def test_percent_in_prefix_is_literal(self):
        self.assertEqual(names(search(self.conn, "a%", 10)), ["a%b"])

    def test_underscore_in_prefix_is_literal(self):
        self.assertEqual(names(search(self.conn, "a_", 10)), ["a_b"])

    def test_backslash_in_prefix_is_literal(self):
        self.assertEqual(names(search(self.conn, "a\\", 10)), ["a\\b"])

    def test_escape_character_before_wildcard(self):
        conn = make_db([(1, "a\\%z"), (2, "a%z"), (3, "a\\z")])
        self.assertEqual(names(search(conn, "a\\%", 10)), ["a\\%z"])

    def test_empty_prefix_matches_all(self):
        self.assertEqual(len(search(self.conn, "", 100)), 8)

    def test_injection_attempts_are_inert(self):
        for payload in ["x' OR '1'='1", "' OR 1=1 --", "%", "_", "'; DROP TABLE users; --"]:
            with self.subTest(payload=payload):
                self.assertEqual(search(self.conn, payload, 100), [] if payload not in ("%", "_") else search(self.conn, payload, 100))
        self.assertEqual(search(self.conn, "x' OR '1'='1", 100), [])
        self.assertEqual(self.conn.execute("SELECT COUNT(*) FROM users").fetchone()[0], 8)

    def test_ordering_is_name_then_id(self):
        conn = make_db([(3, "Amy"), (1, "Amy"), (4, "Amz"), (2, "Amy")])
        self.assertEqual(search(conn, "Am", 10), [(1, "Amy"), (2, "Amy"), (3, "Amy"), (4, "Amz")])

    def test_limit_is_clamped_to_max(self):
        conn = make_db([(i, "u%03d" % i) for i in range(1, 151)])
        self.assertEqual(len(search(conn, "u", 500)), 100)

    def test_limit_is_clamped_to_min(self):
        conn = make_db([(i, "u%03d" % i) for i in range(1, 6)])
        self.assertEqual(len(search(conn, "u", 0)), 1)
        self.assertEqual(len(search(conn, "u", -7)), 1)

    def test_limit_applies_within_range(self):
        conn = make_db([(i, "u%03d" % i) for i in range(1, 11)])
        self.assertEqual(names(search(conn, "u", 5)), ["u001", "u002", "u003", "u004", "u005"])

    def test_bool_limit_is_rejected(self):
        for value in (True, False):
            with self.subTest(value=value):
                with self.assertRaises(ValueError):
                    search(self.conn, "A", value)

    def test_non_integer_limit_is_rejected(self):
        for value in ("5", 5.0, 1.5, None, [5]):
            with self.subTest(value=value):
                with self.assertRaises(ValueError):
                    search(self.conn, "A", value)

    def test_non_string_prefix_is_rejected(self):
        with self.assertRaises(TypeError):
            search(self.conn, None, 5)


