import csv
import io
import re

_HEADER = ["name", "age"]
_AGE_PATTERN = re.compile(r"[0-9]+")
_MAX_AGE = 130


def read_people(text):
    try:
        records = list(csv.reader(io.StringIO(text), strict=True))
    except csv.Error as exc:
        raise ValueError(f"invalid CSV: {exc}") from exc

    if not records or records[0] != _HEADER:
        raise ValueError("header must be exactly name,age")

    people = []
    for number, record in enumerate(records[1:], start=1):
        if len(record) != 2:
            raise ValueError(f"record {number}: expected 2 columns, got {len(record)}")
        name, age_text = record
        if not _AGE_PATTERN.fullmatch(age_text):
            raise ValueError(f"record {number}: age must be ASCII digits, got {age_text!r}")
        age = int(age_text)
        if age > _MAX_AGE:
            raise ValueError(f"record {number}: age must be 0..{_MAX_AGE}, got {age}")
        people.append({"name": name, "age": age})
    return people

