        for row in reader:
            if len(row) != len(_HEADER):
                raise ValueError(
                    f"line {reader.line_num}: expected {len(_HEADER)} columns, got {len(row)}"
                )
            name, age = row
            people.append({"name": name, "age": _parse_age(age)})
    except csv.Error as exc:
        raise ValueError(f"invalid CSV: {exc}") from exc
    return people

