import csv
import io

HEADER = ["name", "age"]
MIN_AGE = 0
MAX_AGE = 130


def read_people(text):
    try:
        reader = csv.reader(io.StringIO(text, newline=""), strict=True)
        header = next(reader, None)
        if header != HEADER:
            raise ValueError(f"expected header {','.join(HEADER)!r}, got {header!r}")
        people = []
        for row in reader:
            people.append(_parse_row(row, reader.line_num))
    except csv.Error as exc:
        raise ValueError(f"invalid CSV: {exc}") from exc
    return people


def _parse_row(row, line_num):
    if len(row) != len(HEADER):
        raise ValueError(f"line {line_num}: expected {len(HEADER)} columns, got {len(row)}")
    name, age = row
    if not age.isascii() or not age.isdigit():
        raise ValueError(f"line {line_num}: age must be ASCII digits, got {age!r}")
    age_value = int(age)
    if not MIN_AGE <= age_value <= MAX_AGE:
        raise ValueError(f"line {line_num}: age {age_value} outside {MIN_AGE}..{MAX_AGE}")
    return {"name": name, "age": age_value}

