async function collectPages(fetchPage) {
  const items = [];
  const requested = new Set();
  let cursor = null;
  for (;;) {
    if (cursor !== null) {
      if (requested.has(cursor)) {
        throw new Error(`collectPages: cursor requested twice: ${JSON.stringify(cursor)}`);
      }
      requested.add(cursor);
    }
    const page = await fetchPage(cursor);
    for (const item of page.items) {
      items.push(item);
    }
    if (page.next === null) {
      return items;
    }
    cursor = page.next;
  }
}

module.exports = { collectPages };

const { test } = require('node:test');
const assert = require('node:assert/strict');
const { collectPages } = require('../src/solution.cjs');

function scripted(pages) {
  const calls = [];
  const fetchPage = async (cursor) => {
    calls.push(cursor);
    const page = pages[calls.length - 1];
    if (page === undefined) throw new Error('unexpected extra fetch');
    return page;
  };
  return { fetchPage, calls };
}

test('appends items from every page in order, keeping duplicates', async () => {
  const { fetchPage, calls } = scripted([
    { items: [1, 2, 2], next: 'a' },
    { items: [3], next: 'b' },
    { items: [2, 1], next: null },
  ]);
  assert.deepEqual(await collectPages(fetchPage), [1, 2, 2, 3, 2, 1]);
  assert.deepEqual(calls, [null, 'a', 'b']);
});

test('returns an empty array for a single empty last page', async () => {
  const { fetchPage } = scripted([{ items: [], next: null }]);
  assert.deepEqual(await collectPages(fetchPage), []);
});

test('continues past an empty intermediate page', async () => {
  const { fetchPage, calls } = scripted([
    { items: ['x'], next: 'p2' },
    { items: [], next: 'p3' },
    { items: ['y'], next: null },
  ]);
  assert.deepEqual(await collectPages(fetchPage), ['x', 'y']);
  assert.deepEqual(calls, [null, 'p2', 'p3']);
});

test('treats empty-string next as a real cursor, not as the end', async () => {
  const { fetchPage, calls } = scripted([
    { items: [1], next: '' },
    { items: [2], next: null },
  ]);
  assert.deepEqual(await collectPages(fetchPage), [1, 2]);
  assert.deepEqual(calls, [null, '']);
});

test('throws when a non-null cursor would be requested twice', async () => {
  const { fetchPage, calls } = scripted([
    { items: [1], next: 'a' },
    { items: [2], next: 'b' },
    { items: [3], next: 'a' },
  ]);
  await assert.rejects(collectPages(fetchPage), /cursor requested twice/);
  assert.deepEqual(calls, [null, 'a', 'b']);
});

test('throws on a self-referencing cursor without fetching again', async () => {
  const { fetchPage, calls } = scripted([
    { items: [], next: 'loop' },
    { items: [], next: 'loop' },
  ]);
  await assert.rejects(collectPages(fetchPage), /cursor requested twice/);
  assert.deepEqual(calls, [null, 'loop']);
});

test('treats a repeated empty-string cursor as a repeat', async () => {
  const { fetchPage, calls } = scripted([
    { items: [], next: '' },
    { items: [], next: '' },
  ]);
  await assert.rejects(collectPages(fetchPage), /cursor requested twice/);
  assert.deepEqual(calls, [null, '']);
});

test('propagates a rejected fetch with the same error', async () => {
  const boom = new Error('network down');
  const { fetchPage, calls } = scripted([{ items: [1], next: 'a' }]);
  const failing = async (cursor) => {
    if (cursor === 'a') throw boom;
    return fetchPage(cursor);
  };
  await assert.rejects(collectPages(failing), (err) => err === boom);
  assert.deepEqual(calls, [null]);
});

test('propagates a synchronous throw from fetchPage as a rejection', async () => {
  const boom = new Error('bad input');
  await assert.rejects(
    collectPages(() => {
      throw boom;
    }),
    (err) => err === boom,
