'use strict';

const UNSAFE_KEYS = new Set(['__proto__', 'constructor', 'prototype']);

function hasOwn(object, key) {
  return Object.prototype.hasOwnProperty.call(object, key);
}

function isPlainObject(value) {
  if (value === null || typeof value !== 'object') return false;
  const proto = Object.getPrototypeOf(value);
  return proto === Object.prototype || proto === null;
}

function assertJsonLike(value, path, ancestors) {
  if (value === null || typeof value === 'string' || typeof value === 'boolean') return;
  if (typeof value === 'number') {
    if (!Number.isFinite(value)) throw new TypeError(`${path} is not a finite number`);
    return;
  }
  if (typeof value !== 'object') throw new TypeError(`${path} is not JSON-like: ${typeof value}`);
  if (!Array.isArray(value) && !isPlainObject(value)) {
    throw new TypeError(`${path} is not a plain object or array`);
  }
  if (ancestors.has(value)) throw new TypeError(`${path} contains a cycle`);

  for (const key of Reflect.ownKeys(value)) {
    if (typeof key === 'symbol') throw new TypeError(`${path} has a symbol key`);
    if (UNSAFE_KEYS.has(key)) throw new TypeError(`${path} has unsafe key "${key}"`);
  }

  ancestors.add(value);
  if (Array.isArray(value)) {
    for (let i = 0; i < value.length; i++) {
      if (!hasOwn(value, i)) throw new TypeError(`${path}[${i}] is a hole`);
      assertJsonLike(value[i], `${path}[${i}]`, ancestors);
    }
  } else {
    for (const key of Object.keys(value)) {
      assertJsonLike(value[key], `${path}.${key}`, ancestors);
    }
  }
  ancestors.delete(value);
}

function assertConfig(value, name) {
  if (!isPlainObject(value)) throw new TypeError(`${name} must be a plain object`);
  assertJsonLike(value, name, new Set());
}

function copyValue(value) {
  if (Array.isArray(value)) return value.map(copyValue);
  if (!isPlainObject(value)) return value;
  const copy = {};
  for (const key of Object.keys(value)) {
    copy[key] = copyValue(value[key]);
  }
  return copy;
}

function mergeObjects(base, override) {
  const result = {};
  for (const key of Object.keys(base)) {
    if (!hasOwn(override, key)) result[key] = copyValue(base[key]);
  }
  for (const key of Object.keys(override)) {
    const bothPlain =
      hasOwn(base, key) && isPlainObject(base[key]) && isPlainObject(override[key]);
    result[key] = bothPlain
      ? mergeObjects(base[key], override[key])
      : copyValue(override[key]);
  }
  return result;
}

function mergeConfig(base, override) {
  assertConfig(base, 'base');
  assertConfig(override, 'override');
  return mergeObjects(base, override);
}

module.exports = { mergeConfig };

