const UNSAFE_KEYS = new Set(['__proto__', 'constructor', 'prototype']);

function isPlainObject(value) {
  if (value === null || typeof value !== 'object' || Array.isArray(value)) return false;
  const proto = Object.getPrototypeOf(value);
  return proto === Object.prototype || proto === null;
}

function assertKeyAllowed(key, path) {
  if (typeof key === 'symbol') throw new TypeError(`Symbol key at ${path} is not JSON-like`);
  if (UNSAFE_KEYS.has(key)) throw new TypeError(`Unsafe key "${key}" at ${path}`);
}

function assertJsonLike(value, path) {
  if (value === null || typeof value === 'string' || typeof value === 'boolean') return;
  if (typeof value === 'number') {
    if (!Number.isFinite(value)) throw new TypeError(`Non-finite number at ${path}`);
    return;
  }
  if (Array.isArray(value)) {
    for (const key of Reflect.ownKeys(value)) {
      if (key !== 'length') assertKeyAllowed(key, path);
    }
    for (let i = 0; i < value.length; i++) assertJsonLike(value[i], `${path}[${i}]`);
    return;
  }
  if (isPlainObject(value)) {
    for (const key of Reflect.ownKeys(value)) assertKeyAllowed(key, path);
    for (const key of Object.keys(value)) assertJsonLike(value[key], `${path}.${key}`);
    return;
  }
  throw new TypeError(`Value at ${path} is not JSON-like`);
}

function deepCopy(value) {
  if (Array.isArray(value)) return value.map(deepCopy);
  if (isPlainObject(value)) {
    const copy = {};
    for (const key of Object.keys(value)) copy[key] = deepCopy(value[key]);
    return copy;
  }
  return value;
}

function mergeValues(base, override) {
  if (!isPlainObject(base) || !isPlainObject(override)) return deepCopy(override);
  const result = {};
  for (const key of Object.keys(base)) {
    result[key] = Object.hasOwn(override, key)
      ? mergeValues(base[key], override[key])
      : deepCopy(base[key]);
  }
  for (const key of Object.keys(override)) {
    if (!Object.hasOwn(base, key)) result[key] = deepCopy(override[key]);
  }
  return result;
}

// Both inputs are validated in full first: a base subtree that the override replaces is still an input and must be checked.
function mergeConfig(base, override) {
  assertJsonLike(base, 'base');
  assertJsonLike(override, 'override');
  return mergeValues(base, override);
}

