const UNSAFE_KEYS = new Set(['__proto__', 'constructor', 'prototype']);

function isPlainObject(value) {
  if (value === null || typeof value !== 'object' || Array.isArray(value)) {
    return false;
  }
  const proto = Object.getPrototypeOf(value);
  return proto === Object.prototype || proto === null;
}

function assertJsonLike(value, path) {
  if (value === null) {
    return;
  }

  const type = typeof value;
  if (type === 'string' || type === 'number' || type === 'boolean') {
    return;
  }

  if (Array.isArray(value)) {
    value.forEach((item, index) => assertJsonLike(item, `${path}[${index}]`));
    return;
  }

  if (!isPlainObject(value)) {
    throw new TypeError(`Unsupported value at ${path}: ${type}`);
  }

  for (const key of Object.getOwnPropertyNames(value)) {
    if (UNSAFE_KEYS.has(key)) {
      throw new Error(`Unsafe key "${key}" at ${path}`);
    }
  }

  for (const key of Object.keys(value)) {
    assertJsonLike(value[key], `${path}.${key}`);
  }
}

function deepCopy(value) {
  if (Array.isArray(value)) {
    return value.map(deepCopy);
  }
  if (isPlainObject(value)) {
    const copy = {};
    for (const key of Object.keys(value)) {
      copy[key] = deepCopy(value[key]);
    }
    return copy;
  }
  return value;
}

function mergeValues(base, override) {
  if (!isPlainObject(base) || !isPlainObject(override)) {
    return deepCopy(override);
  }

  const result = {};
  for (const key of Object.keys(base)) {
    result[key] = deepCopy(base[key]);
  }

  for (const key of Object.keys(override)) {
    const overrideValue = override[key];
    if (Object.hasOwn(base, key) && isPlainObject(base[key]) && isPlainObject(overrideValue)) {
      result[key] = mergeValues(base[key], overrideValue);
    } else {
      result[key] = deepCopy(overrideValue);
    }
  }

  return result;
}

function mergeConfig(base, override) {
  if (!isPlainObject(base) || !isPlainObject(override)) {
    throw new TypeError('mergeConfig expects plain object arguments');
  }

  assertJsonLike(base, 'base');
  assertJsonLike(override, 'override');

  return mergeValues(base, override);
}

