const UNSAFE_KEYS = ['__proto__', 'constructor', 'prototype'];

function collectRefs(value, refs = new Set()) {
  if (value !== null && typeof value === 'object') {
    refs.add(value);
    for (const child of Object.values(value)) {
      collectRefs(child, refs);
    }
  }
  return refs;
}

