'use strict';

const UNSAFE_KEYS = new Set(['__proto__', 'constructor', 'prototype']);

function isPlainObject(value) {
  if (typeof value !== 'object' || value === null) return false;
  const proto = Object.getPrototypeOf(value);
  return proto === Object.prototype || proto === null;
}

function hasOwn(object, key) {
  return Object.prototype.hasOwnProperty.call(object, key);
}

// Validates both inputs up front: a key unsafe in a subtree that override replaces would otherwise go unchecked.
function validate(value, path) {
  if (typeof value === 'function' || (typeof value === 'object' && value !== null && !Array.isArray(value) && !isPlainObject(value))) {
    throw new TypeError(`Unsupported value at ${path}; only JSON-like values are allowed`);
  }
  if (typeof value !== 'object' || value === null) return;
  for (const key of Reflect.ownKeys(value)) {
    if (typeof key === 'string' && UNSAFE_KEYS.has(key)) {
      throw new TypeError(`Unsafe key "${key}" at ${path}`);
    }
  }
  for (const key of Object.keys(value)) {
    validate(value[key], `${path}.${key}`);
  }
}

function deepCopy(value) {
  if (Array.isArray(value)) return value.map(deepCopy);
  if (isPlainObject(value)) {
    const copy = {};
    for (const key of Object.keys(value)) {
      copy[key] = deepCopy(value[key]);
    }
    return copy;
  }
  return value;
}

function mergeValues(base, override) {
  if (!isPlainObject(base) || !isPlainObject(override)) return deepCopy(override);
  const result = {};
  for (const key of Object.keys(base)) {
    if (!hasOwn(override, key)) result[key] = deepCopy(base[key]);
  }
  for (const key of Object.keys(override)) {
    result[key] = mergeValues(hasOwn(base, key) ? base[key] : undefined, override[key]);
  }
  return result;
}

function mergeConfig(base, override) {
  validate(base, 'base');
  validate(override, 'override');
  return mergeValues(base, override);
}

module.exports = { mergeConfig };

