'use strict';

const UNSAFE_KEYS = new Set(['__proto__', 'constructor', 'prototype']);

function hasOwn(object, key) {
  return Object.prototype.hasOwnProperty.call(object, key);
}

function isPlainObject(value) {
  if (value === null || typeof value !== 'object') {
    return false;
  }
  const proto = Object.getPrototypeOf(value);
  return proto === Object.prototype || proto === null;
}

function assertJsonLike(value, path) {
  if (value !== null && typeof value === 'object') {
    if (!Array.isArray(value) && !isPlainObject(value)) {
      throw new TypeError(`Unsupported non-plain object at ${path}`);
    }
    for (const key of Object.getOwnPropertyNames(value)) {
      if (UNSAFE_KEYS.has(key)) {
        throw new TypeError(`Unsafe key "${key}" at ${path}`);
      }
    }
    if (Array.isArray(value)) {
      value.forEach((item, index) => assertJsonLike(item, `${path}[${index}]`));
    } else {
      for (const key of Object.keys(value)) {
        assertJsonLike(value[key], `${path}.${key}`);
      }
    }
    return;
  }
  const type = typeof value;
  if (type === 'function' || type === 'symbol' || type === 'bigint') {
    throw new TypeError(`Unsupported ${type} at ${path}`);
  }
}

function deepCopy(value) {
  if (Array.isArray(value)) {
    return value.map(deepCopy);
  }
  if (isPlainObject(value)) {
    const copy = {};
    for (const key of Object.keys(value)) {
      copy[key] = deepCopy(value[key]);
    }
    return copy;
  }
  return value;
}

function mergeValues(base, override) {
  if (!isPlainObject(base) || !isPlainObject(override)) {
    return deepCopy(override);
  }
  const result = {};
  for (const key of Object.keys(base)) {
    result[key] = hasOwn(override, key)
      ? mergeValues(base[key], override[key])
      : deepCopy(base[key]);
  }
  for (const key of Object.keys(override)) {
    if (!hasOwn(base, key)) {
      result[key] = deepCopy(override[key]);
    }
  }
  return result;
}

function mergeConfig(base, override) {
  assertJsonLike(base, 'base');
  assertJsonLike(override, 'override');
  return mergeValues(base, override);
}

module.exports = { mergeConfig };

'use strict';

const { test } = require('node:test');
const assert = require('node:assert/strict');
const { mergeConfig } = require('../src/solution.cjs');

const UNSAFE_KEYS = ['__proto__', 'constructor', 'prototype'];

function objectWithOwnKey(key, value) {
  const obj = {};
  Object.defineProperty(obj, key, { value, enumerable: true, writable: true, configurable: true });
  return obj;
}

function collectContainers(value, found = new Set()) {
  if (value !== null && typeof value === 'object') {
    found.add(value);
    for (const item of Object.values(value)) {
      collectContainers(item, found);
    }
  }
  return found;
}

