const MAX_SAFE = Number.MAX_SAFE_INTEGER;

function validate(total, weights) {
  if (!Number.isSafeInteger(total) || total < 0) {
    throw new RangeError("total must be a nonnegative safe integer");
  }
  if (!Array.isArray(weights) || weights.length === 0) {
    throw new RangeError("weights must be a nonempty array");
  }

  let sum = 0;
  for (let i = 0; i < weights.length; i++) {
    const weight = weights[i];
    if (!Number.isSafeInteger(weight) || weight <= 0) {
      throw new RangeError(`weights[${i}] must be a positive safe integer`);
    }
    sum += weight;
    if (sum > MAX_SAFE) {
      throw new RangeError("sum of weights must be a safe integer");
    }
    if (total * weight > MAX_SAFE) {
      throw new RangeError(`total * weights[${i}] must be a safe integer`);
    }
  }
  return sum;
}

function splitCents(total, weights) {
  const sum = validate(total, weights);

  const shares = [];
  const remainders = [];
  let allocated = 0;
  for (const weight of weights) {
    const product = total * weight;
    const remainder = product % sum;
    const floor = (product - remainder) / sum;
    shares.push(floor);
    remainders.push(remainder);
    allocated += floor;
  }

  const leftover = total - allocated;
  const order = weights
    .map((_, i) => i)
    .sort((a, b) => remainders[b] - remainders[a] || a - b);
  for (let k = 0; k < leftover; k++) {
    shares[order[k]] += 1;
  }
  return shares;
}

module.exports = { splitCents };

