  assert.deepEqual(splitCents(10, [1, 1, 1]), [4, 3, 3]);
  assert.deepEqual(splitCents(1, [1, 1]), [1, 0]);
  assert.deepEqual(splitCents(2, [1, 1, 1]), [1, 1, 0]);
  assert.deepEqual(splitCents(5, [2, 2, 2, 2]), [2, 1, 1, 1]);
