test("zero total yields all zeros", () => {
  assert.deepEqual(splitCents(0, [1, 2, 3]), [0, 0, 0]);
  assert.deepEqual(splitCents(0, [7]), [0]);
});

test("uneven quotas use largest fractional remainders", () => {
  assert.deepEqual(splitCents(10, [1, 2, 3]), [2, 3, 5]);
  assert.deepEqual(splitCents(7, [5, 3, 1]), [4, 2, 1]);
