'use strict';

function splitCents(total, weights) {
  if (!Number.isSafeInteger(total) || total < 0) {
    throw new RangeError('total must be a nonnegative safe integer');
  }
  if (!Array.isArray(weights) || weights.length === 0) {
    throw new RangeError('weights must be a nonempty array');
  }

  let weightSum = 0;
  for (const weight of weights) {
    if (!Number.isSafeInteger(weight) || weight <= 0) {
      throw new RangeError('weights must be positive safe integers');
    }
    weightSum += weight;
    if (!Number.isSafeInteger(weightSum) || !Number.isSafeInteger(total * weight)) {
      throw new RangeError('weight sum and total * weight must be safe integers');
    }
  }

  const bigTotal = BigInt(total);
  const bigWeightSum = BigInt(weightSum);
  const shares = weights.map((weight) => {
    const product = bigTotal * BigInt(weight);
    return { cents: product / bigWeightSum, remainder: product % bigWeightSum };
  });

  const allocated = shares.reduce((sum, share) => sum + share.cents, 0n);
  let leftover = Number(bigTotal - allocated);

  const order = shares
    .map((_, index) => index)
    .sort((a, b) => {
      if (shares[a].remainder !== shares[b].remainder) {
        return shares[a].remainder > shares[b].remainder ? -1 : 1;
      }
      return a - b;
    });

  for (let k = 0; k < leftover; k++) {
    shares[order[k]].cents += 1n;
  }

  return shares.map((share) => Number(share.cents));
}

module.exports = { splitCents };

'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const { splitCents } = require('../src/solution.cjs');

test('splits evenly when the total divides exactly', () => {
  assert.deepEqual(splitCents(9, [1, 1, 1]), [3, 3, 3]);
});

test('ties in remainders go to earlier indices', () => {
  assert.deepEqual(splitCents(5, [1, 1]), [3, 2]);
  assert.deepEqual(splitCents(2, [1, 1, 1]), [1, 1, 0]);
  assert.deepEqual(splitCents(1, [1, 1, 1]), [1, 0, 0]);
});

test('larger remainder wins over an earlier index', () => {
  assert.deepEqual(splitCents(2, [2, 1]), [1, 1]);
});

test('zero total yields all zeros with one entry per weight', () => {
  assert.deepEqual(splitCents(0, [3, 5, 7]), [0, 0, 0]);
  assert.deepEqual(splitCents(0, [1]), [0]);
});

test('uneven quotas are floored and leftover goes to largest remainders', () => {
  assert.deepEqual(splitCents(100, [1, 2, 3]), [17, 33, 50]);
  assert.deepEqual(splitCents(10, [1, 2, 3]), [2, 3, 5]);
});

test('exact arithmetic near the safe integer limit', () => {
  const max = Number.MAX_SAFE_INTEGER;
  assert.deepEqual(splitCents(max, [1, 1]), [4503599627370496, 4503599627370495]);
  const shares = splitCents(max, [1, 2, 3, 4]);
  assert.equal(shares.reduce((a, b) => a + b, 0), max);
});

test('result always sums exactly to total', () => {
  const weightSets = [[1], [1, 2, 3], [7, 11, 13, 17], [1, 1, 1, 1, 1, 1, 1]];
  for (const weights of weightSets) {
    for (let total = 0; total <= 200; total++) {
      const shares = splitCents(total, weights);
      assert.equal(shares.length, weights.length);
      assert.equal(shares.reduce((a, b) => a + b, 0), total);
      assert.ok(shares.every((n) => Number.isSafeInteger(n) && n >= 0));
    }
  }
});

test('does not mutate weights', () => {
  const weights = [3, 1, 2];
  splitCents(10, weights);
  assert.deepEqual(weights, [3, 1, 2]);
});

test('throws RangeError for invalid total', () => {
  for (const total of [-1, 1.5, NaN, Infinity, '3', null, 2 ** 53, 10n]) {
    assert.throws(() => splitCents(total, [1]), RangeError);
  }
});

test('throws RangeError for invalid weights', () => {
  const bad = [
    [],
    undefined,
    'abc',
    [0],
    [-1],
    [1.5],
    ['2'],
    [1, 0],
    [null],
    [2 ** 53],
  ];
  for (const weights of bad) {
    assert.throws(() => splitCents(10, weights), RangeError);
  }
});

test('throws RangeError when weight sum exceeds the safe range', () => {
  assert.throws(() => splitCents(1, [Number.MAX_SAFE_INTEGER, 2]), RangeError);
});

test('throws RangeError when total * weight exceeds the safe range', () => {
  assert.throws(() => splitCents(Number.MAX_SAFE_INTEGER, [2]), RangeError);
});

