function splitCents(total, weights) {
  if (!Number.isSafeInteger(total) || total < 0) {
    throw new RangeError('total must be a nonnegative safe integer');
  }
  if (!Array.isArray(weights) || weights.length === 0) {
    throw new RangeError('weights must be a nonempty array');
  }

  let weightSum = 0;
  for (let i = 0; i < weights.length; i++) {
    const weight = weights[i];
    if (!Number.isSafeInteger(weight) || weight <= 0) {
      throw new RangeError(`weights[${i}] must be a positive safe integer`);
    }
    weightSum += weight;
    if (!Number.isSafeInteger(weightSum)) {
      throw new RangeError('sum of weights must be a safe integer');
    }
    if (!Number.isSafeInteger(total * weight)) {
      throw new RangeError(`total * weights[${i}] must be a safe integer`);
    }
  }

  const shares = new Array(weights.length);
  const remainders = new Array(weights.length);
  let allocated = 0;
  for (let i = 0; i < weights.length; i++) {
    const product = total * weights[i];
    const remainder = product % weightSum;
    const quota = (product - remainder) / weightSum;
    shares[i] = quota;
    remainders[i] = remainder;
    allocated += quota;
  }

  const leftover = total - allocated;
  const order = remainders.map((_, i) => i);
  order.sort((a, b) => remainders[b] - remainders[a] || a - b);
  for (let k = 0; k < leftover; k++) {
    shares[order[k]] += 1;
  }

  return shares;
}

module.exports = { splitCents };

const { test } = require('node:test');
const assert = require('node:assert/strict');
const { splitCents } = require('../src/solution.cjs');

const sum = (xs) => xs.reduce((a, b) => a + b, 0);

test('uneven quotas: leftover goes to largest remainder', () => {
  // quotas 1.67, 3.33, 5 -> floors 1, 3, 5 with remainders 4, 2, 0; leftover 1 goes to index 0
  assert.deepEqual(splitCents(10, [1, 2, 3]), [2, 3, 5]);
});

test('exact division needs no leftover distribution', () => {
  assert.deepEqual(splitCents(12, [1, 1, 2]), [3, 3, 6]);
});

test('uneven quotas with weights in non-sorted order', () => {
  assert.deepEqual(splitCents(7, [3, 1, 3]), [3, 1, 3]);
  assert.deepEqual(splitCents(100, [1, 2, 4]), [14, 29, 57]);
});

test('ties: equal remainders go to earlier index', () => {
  assert.deepEqual(splitCents(5, [1, 1]), [3, 2]);
  assert.deepEqual(splitCents(10, [1, 1, 1]), [4, 3, 3]);
  assert.deepEqual(splitCents(2, [1, 1, 1]), [1, 1, 0]);
});

test('ties: earlier index wins even when a later weight is larger', () => {
  // remainders are 2, 2, 1 -> leftover 1 goes to index 0
  assert.deepEqual(splitCents(1, [2, 2, 1]), [1, 0, 0]);
});

test('zero total returns all zeros', () => {
  assert.deepEqual(splitCents(0, [1, 2, 3]), [0, 0, 0]);
  assert.deepEqual(splitCents(0, [5]), [0]);
});

test('single weight receives the whole total', () => {
  assert.deepEqual(splitCents(7, [4]), [7]);
  assert.deepEqual(splitCents(1, [Number.MAX_SAFE_INTEGER]), [1]);
});

