  const result = splitCents(Number.MAX_SAFE_INTEGER, [1, 1]);
  assert.deepEqual(result, [4503599627370496, 4503599627370495]);
  assert.equal(sum(result), Number.MAX_SAFE_INTEGER);
});

test('result always sums exactly to total and has one entry per weight', () => {
  const cases = [
    [1, [1]],
    [17, [1, 2, 3, 4]],
    [999, [7, 11, 13]],
    [12345, [1, 1, 1, 1, 1]],
  ];
  for (const [total, weights] of cases) {
    const result = splitCents(total, weights);
    assert.equal(result.length, weights.length);
    assert.equal(sum(result), total);
  }
});

test('does not mutate weights', () => {
  const weights = [3, 1, 2];
  const copy = [...weights];
  splitCents(10, weights);
  assert.deepEqual(weights, copy);
});

test('invalid total throws RangeError', () => {
  for (const total of [-1, 1.5, NaN, Infinity, '5', null, undefined, 2 ** 53]) {
    assert.throws(() => splitCents(total, [1]), RangeError);
  }
});

test('invalid weights throw RangeError', () => {
  for (const weights of [undefined, '12', {}, [], [0], [-1], [1.5], ['2'], [NaN], [1, 0]]) {
    assert.throws(() => splitCents(5, weights), RangeError);
  }
});

test('sum of weights overflowing safe range throws RangeError', () => {
  assert.throws(() => splitCents(0, [Number.MAX_SAFE_INTEGER, 1]), RangeError);
});

test('total * weight overflowing safe range throws RangeError', () => {
  assert.throws(() => splitCents(2, [2 ** 52]), RangeError);
});

