'use strict';

function splitCents(total, weights) {
  if (!Number.isSafeInteger(total) || total < 0) {
    throw new RangeError('total must be a nonnegative safe integer');
  }
  if (!Array.isArray(weights) || weights.length === 0) {
    throw new RangeError('weights must be a nonempty array');
  }

  let sum = 0;
  for (const weight of weights) {
    if (!Number.isSafeInteger(weight) || weight <= 0) {
      throw new RangeError('weights must contain only positive safe integers');
    }
    sum += weight;
  }
  if (!Number.isSafeInteger(sum)) {
    throw new RangeError('sum of weights must be a safe integer');
  }
  for (const weight of weights) {
    if (!Number.isSafeInteger(total * weight)) {
      throw new RangeError('total * weight must be a safe integer');
    }
  }

  const bigTotal = BigInt(total);
  const bigSum = BigInt(sum);
  const shares = weights.map((weight) => {
    const product = bigTotal * BigInt(weight);
    return { floor: product / bigSum, remainder: product % bigSum };
  });

  let allocated = 0n;
  for (const share of shares) {
    allocated += share.floor;
  }
  const leftover = bigTotal - allocated;

  const order = shares.map((_, index) => index);
  order.sort((a, b) => {
    const diff = shares[b].remainder - shares[a].remainder;
    if (diff > 0n) return 1;
    if (diff < 0n) return -1;
    return a - b;
  });

  const result = shares.map((share) => Number(share.floor));
  for (let i = 0n; i < leftover; i++) {
    result[order[Number(i)]] += 1;
  }
  return result;
}

module.exports = { splitCents };

