from datetime import datetime, timezone


def utc_day_start(text):
    if not isinstance(text, str):
        raise ValueError(f"timestamp must be a string, got {type(text).__name__}")
    if text.endswith("Z"):
        text = text[:-1] + "+00:00"
    try:
        instant = datetime.fromisoformat(text)
    except ValueError:
        raise ValueError(f"invalid ISO 8601 timestamp: {text!r}") from None
    if instant.utcoffset() is None:
        raise ValueError(f"timestamp must include a UTC offset or Z: {text!r}")
    try:
        utc = instant.astimezone(timezone.utc)
    except OverflowError:
        raise ValueError(f"timestamp is outside the supported UTC range: {text!r}") from None
    return utc.replace(hour=0, minute=0, second=0, microsecond=0)

import os
import sys
import time
import unittest
from datetime import datetime, timezone
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent.parent / "src"))

from solution import utc_day_start  # noqa: E402

UTC = timezone.utc


class UtcDayStartTests(unittest.TestCase):
    def test_spec_example_positive_offset_falls_on_previous_utc_day(self):
        self.assertEqual(
            utc_day_start("2025-01-01T00:30:00+02:00"),
            datetime(2024, 12, 31, tzinfo=UTC),
        )

    def test_negative_offset_moves_evening_into_next_utc_day(self):
        # 2025-12-31T20:00-05:00 is 2026-01-01T01:00Z
        self.assertEqual(
            utc_day_start("2025-12-31T20:00:00-05:00"),
            datetime(2026, 1, 1, tzinfo=UTC),
        )

    def test_offset_keeps_same_local_date_on_same_utc_day(self):
        self.assertEqual(
            utc_day_start("2025-06-15T10:00:00+05:30"),
            datetime(2025, 6, 15, tzinfo=UTC),
        )

    def test_offset_with_minutes_crosses_day_boundary(self):
        # 2025-03-10T00:15+00:30 is 2025-03-09T23:45Z
        self.assertEqual(
            utc_day_start("2025-03-10T00:15:00+00:30"),
            datetime(2025, 3, 9, tzinfo=UTC),
        )

    def test_z_suffix_uses_utc_day(self):
        self.assertEqual(
            utc_day_start("2025-07-04T23:59:59Z"),
            datetime(2025, 7, 4, tzinfo=UTC),
        )

    def test_explicit_zero_offset_matches_z(self):
        self.assertEqual(
            utc_day_start("2025-07-04T00:00:00+00:00"),
            utc_day_start("2025-07-04T00:00:00Z"),
        )

    def test_exact_utc_midnight_is_its_own_day(self):
        self.assertEqual(
            utc_day_start("2025-08-01T00:00:00Z"),
            datetime(2025, 8, 1, tzinfo=UTC),
        )

    def test_fractional_seconds_do_not_change_day(self):
        self.assertEqual(
            utc_day_start("2025-08-01T23:59:59.999999+00:00"),
            datetime(2025, 8, 1, tzinfo=UTC),
        )

    def test_leap_day_utc_instant(self):
        self.assertEqual(
            utc_day_start("2024-02-29T12:00:00Z"),
            datetime(2024, 2, 29, tzinfo=UTC),
        )

    def test_leap_day_local_time_shifts_to_march_first_utc(self):
        # 2024-02-29T23:30-05:00 is 2024-03-01T04:30Z
        self.assertEqual(
            utc_day_start("2024-02-29T23:30:00-05:00"),
            datetime(2024, 3, 1, tzinfo=UTC),
        )

    def test_leap_day_local_time_shifts_to_previous_day_utc(self):
        # 2024-02-29T00:30+01:00 is 2024-02-28T23:30Z
        self.assertEqual(
            utc_day_start("2024-02-29T00:30:00+01:00"),
            datetime(2024, 2, 28, tzinfo=UTC),
        )

    def test_non_leap_year_feb_28_evening_rolls_into_march(self):
        # 2025-02-28T23:00-02:00 is 2025-03-01T01:00Z
        self.assertEqual(
            utc_day_start("2025-02-28T23:00:00-02:00"),
            datetime(2025, 3, 1, tzinfo=UTC),
        )

    def test_result_is_utc_aware_midnight(self):
        result = utc_day_start("2025-01-01T13:45:12.5+09:00")
        self.assertEqual(result, datetime(2025, 1, 1, tzinfo=UTC))
        self.assertIs(result.tzinfo, timezone.utc)
        self.assertEqual(result.utcoffset().total_seconds(), 0)
        self.assertEqual(
            (result.hour, result.minute, result.second, result.microsecond),
            (0, 0, 0, 0),
        )

    def test_does_not_depend_on_machine_timezone(self):
        if not hasattr(time, "tzset"):
            self.skipTest("time.tzset is not available on this platform")
        original = os.environ.get("TZ")
        try:
            expected = utc_day_start("2025-01-01T00:30:00+02:00")
            for zone in ("America/New_York", "Asia/Kathmandu", "Pacific/Kiritimati"):
                os.environ["TZ"] = zone
                time.tzset()
                self.assertEqual(utc_day_start("2025-01-01T00:30:00+02:00"), expected)
        finally:
            if original is None:
                os.environ.pop("TZ", None)
            else:
                os.environ["TZ"] = original
            time.tzset()

    def test_naive_datetime_is_rejected(self):
        for text in ("2025-01-01T00:30:00", "2025-01-01 00:30:00"):
            with self.subTest(text=text):
                with self.assertRaises(ValueError):
                    utc_day_start(text)

    def test_date_only_is_rejected_as_naive(self):
        with self.assertRaises(ValueError):
            utc_day_start("2025-01-01")

    def test_invalid_strings_are_rejected(self):
        for text in (
            "",
            "not a timestamp",
            "2025-13-01T00:00:00Z",
            "2025-02-29T00:00:00Z",
            "2025-01-01T25:00:00Z",
            "2025-01-01T00:00:00+24:00",
            "Z",
        ):
            with self.subTest(text=text):
                with self.assertRaises(ValueError):
                    utc_day_start(text)

    def test_non_string_input_is_rejected(self):
        for value in (None, 1735691400, datetime(2025, 1, 1, tzinfo=UTC)):
            with self.subTest(value=value):
                with self.assertRaises(ValueError):
                    utc_day_start(value)

    def test_instant_outside_representable_utc_range_is_rejected(self):
        for text in ("0001-01-01T00:00:00+01:00", "9999-12-31T23:00:00-05:00"):
            with self.subTest(text=text):
                with self.assertRaises(ValueError):
                    utc_day_start(text)


