import re
from datetime import datetime, timedelta, timezone

_TIMESTAMP = re.compile(
    r"([0-9]{4})-([0-9]{2})-([0-9]{2})"
    r"T([0-9]{2}):([0-9]{2})(?::([0-9]{2})(?:\.([0-9]+))?)?"
    r"(Z|[+-][0-9]{2}:[0-9]{2})"
)


def utc_day_start(text):
    if not isinstance(text, str):
        raise ValueError("timestamp must be a string")
    match = _TIMESTAMP.fullmatch(text)
    if match is None:
        raise ValueError(f"invalid ISO 8601 timestamp with UTC offset: {text!r}")

    year, month, day, hour, minute, second, fraction, zone = match.groups()
    microsecond = int((fraction or "").ljust(6, "0")[:6])

    if zone == "Z":
        offset = timedelta(0)
    else:
        offset_hours = int(zone[1:3])
        offset_minutes = int(zone[4:6])
        if offset_hours > 23 or offset_minutes > 59:
            raise ValueError(f"UTC offset out of range: {zone}")
        offset = timedelta(hours=offset_hours, minutes=offset_minutes)
        if zone[0] == "-":
            offset = -offset

    local = datetime(
        int(year), int(month), int(day),
        int(hour), int(minute), int(second or 0), microsecond,
        tzinfo=timezone(offset),
    )
    try:
        instant = local.astimezone(timezone.utc)
    except OverflowError as exc:
        raise ValueError(f"timestamp out of range once converted to UTC: {text!r}") from exc
    return datetime(instant.year, instant.month, instant.day, tzinfo=timezone.utc)

