        self.assertEqual(decode_chunks([]), "")

    def test_empty_chunks_are_ignored(self):
        self.assertEqual(decode_chunks([b"", b"a", b"", b"b", b""]), "ab")

    def test_ascii_split_arbitrarily(self):
        self.assertEqual(decode_chunks([b"hel", b"lo"]), "hello")

    def test_two_byte_character_split_across_chunks(self):
        # "é" is b"\xc3\xa9"
        self.assertEqual(decode_chunks([b"caf\xc3", b"\xa9"]), "café")

    def test_four_byte_character_split_one_byte_per_chunk(self):
        # "😀" is b"\xf0\x9f\x98\x80"
        chunks = [bytes([b]) for b in "a😀b".encode("utf-8")]
        self.assertEqual(decode_chunks(chunks), "a😀b")

    def test_accepts_lazy_iterable(self):
        def gen():
            yield "naïve ".encode("utf-8")[:3]
            yield "naïve ".encode("utf-8")[3:]

        self.assertEqual(decode_chunks(gen()), "naïve ")

    def test_incomplete_final_character_raises(self):
        with self.assertRaises(UnicodeDecodeError):
