        self.assertEqual(decode_chunks([b"hello"]), "hello")

    def test_multibyte_character_split_across_chunks(self):
        # "é" is b"\xc3\xa9"; split between its two bytes.
        self.assertEqual(decode_chunks([b"caf\xc3", b"\xa9"]), "café")

    def test_four_byte_character_split_one_byte_at_a_time(self):
        data = "a😀b".encode("utf-8")
