const VERSION_PATTERN = /^(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)$/;

function parseVersion(version) {
  if (typeof version !== 'string') {
    throw new TypeError('version must be a string');
  }
  const match = VERSION_PATTERN.exec(version);
  if (match === null) {
    throw new TypeError(`invalid version string: ${JSON.stringify(version)}`);
  }
  return [match[1], match[2], match[3]];
}

function compareComponents(a, b) {
  if (a.length !== b.length) {
    return a.length < b.length ? -1 : 1;
  }
  if (a === b) {
    return 0;
  }
  return a < b ? -1 : 1;
}

function compareVersion(a, b) {
  const left = parseVersion(a);
  const right = parseVersion(b);
  for (let i = 0; i < 3; i++) {
    const result = compareComponents(left[i], right[i]);
    if (result !== 0) {
      return result;
    }
  }
  return 0;
}

module.exports = { compareVersion };

const { test } = require('node:test');
const assert = require('node:assert/strict');
const { compareVersion } = require('../src/solution.cjs');

test('orders components numerically, not lexically', () => {
  assert.equal(compareVersion('1.10.0', '1.2.9'), 1);
  assert.equal(compareVersion('1.2.9', '1.10.0'), -1);
});

test('compares major, minor, then patch in order', () => {
  assert.equal(compareVersion('2.0.0', '1.99.99'), 1);
  assert.equal(compareVersion('1.0.10', '1.1.0'), -1);
  assert.equal(compareVersion('0.0.2', '0.0.1'), 1);
});

test('returns 0 for equal versions', () => {
  assert.equal(compareVersion('0.0.0', '0.0.0'), 0);
  assert.equal(compareVersion('1.2.3', '1.2.3'), 0);
});

test('is antisymmetric', () => {
  const pairs = [
    ['1.10.0', '1.2.9'],
    ['0.0.1', '0.1.0'],
    ['3.0.0', '3.0.0'],
  ];
  for (const [a, b] of pairs) {
    assert.equal(compareVersion(a, b), -compareVersion(b, a));
  }
});

test('compares components beyond Number.MAX_SAFE_INTEGER exactly', () => {
  assert.equal(compareVersion('9007199254740993.0.0', '9007199254740992.0.0'), 1);
  assert.equal(compareVersion('9007199254740992.0.0', '9007199254740993.0.0'), -1);
  assert.equal(compareVersion('9007199254740993.0.0', '9007199254740993.0.0'), 0);
});

test('compares huge components of different lengths', () => {
  assert.equal(
    compareVersion('18446744073709551616.0.0', '18446744073709551615.9999999999999999999.9999'),
    1,
  );
  assert.equal(
    compareVersion('1.99999999999999999999999999.0', '1.100000000000000000000000000.0'),
    -1,
  );
  const big = '1'.padEnd(400, '0');
  assert.equal(compareVersion(`${big}.0.0`, `${big}.0.0`), 0);
  assert.equal(compareVersion(`${big}.0.0`, `${big.slice(1)}.9.9`), 1);
});

test('accepts a single zero and rejects other leading zeros', () => {
  assert.equal(compareVersion('0.0.0', '0.0.0'), 0);
  assert.equal(compareVersion('10.0.0', '1.0.0'), 1);
});

