const VERSION_PATTERN = /^(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)$/;

function parseVersion(value, name) {
  if (typeof value !== 'string') {
    throw new TypeError(`${name} must be a string`);
  }
  const match = VERSION_PATTERN.exec(value);
  if (match === null) {
    throw new TypeError(`${name} must be X.Y.Z with decimal integer components`);
  }
  return [match[1], match[2], match[3]];
}

// Without leading zeros, a longer digit string is numerically larger.
function compareComponent(x, y) {
  if (x.length !== y.length) {
    return x.length < y.length ? -1 : 1;
  }
  if (x === y) {
    return 0;
  }
  return x < y ? -1 : 1;
}

function compareVersion(a, b) {
  const left = parseVersion(a, 'a');
  const right = parseVersion(b, 'b');
  for (let i = 0; i < 3; i++) {
    const result = compareComponent(left[i], right[i]);
    if (result !== 0) {
      return result;
    }
  }
  return 0;
}

module.exports = { compareVersion };

