  }
  const match = VERSION_PATTERN.exec(version);
  if (match === null) {
    throw new TypeError(`${name} is not a valid version: ${JSON.stringify(version)}`);
  }
  return match.slice(1);
}

// Canonical digit strings (no leading zeros) order by length, then lexically; this avoids precision loss.
function compareComponent(x, y) {
  if (x.length !== y.length) {
    return x.length < y.length ? -1 : 1;
  }
  if (x === y) {
    return 0;
  }
  return x < y ? -1 : 1;
}

function compareVersion(a, b) {
  const partsA = parseVersion(a, 'a');
  const partsB = parseVersion(b, 'b');
  for (let i = 0; i < partsA.length; i++) {
    const result = compareComponent(partsA[i], partsB[i]);
    if (result !== 0) {
      return result;
    }
  }
  return 0;
}

