test('returns 0 for equal versions', () => {
  assert.equal(compareVersion('0.0.0', '0.0.0'), 0);
  assert.equal(compareVersion('1.2.3', '1.2.3'), 0);
  assert.equal(compareVersion('10.20.30', '10.20.30'), 0);
});

test('is antisymmetric', () => {
  const pairs = [['1.10.0', '1.2.9'], ['3.0.1', '3.0.1'], ['0.9.9', '1.0.0']];
  for (const [a, b] of pairs) {
    assert.equal(compareVersion(a, b), -compareVersion(b, a) || 0);
  }
});

test('handles components beyond Number.MAX_SAFE_INTEGER', () => {
  const justAboveSafe = '9007199254740993.0.0';
  const safeMax = '9007199254740991.0.0';
  assert.equal(compareVersion(justAboveSafe, '9007199254740992.0.0'), -1);
  assert.equal(compareVersion('9007199254740992.0.0', justAboveSafe), 1);
  assert.equal(compareVersion(justAboveSafe, safeMax), 1);
  assert.equal(compareVersion('1.99999999999999999999999.0', '1.100000000000000000000000.0'), -1);
  assert.equal(compareVersion('1.0.100000000000000000000000', '1.0.99999999999999999999999'), 1);
});

test('huge equal components compare as equal', () => {
  const huge = '123456789012345678901234567890';
  assert.equal(compareVersion(`${huge}.1.1`, `${huge}.1.1`), 0);
  assert.equal(compareVersion(`${huge}.1.1`, `${huge}.1.2`), -1);
});

test('throws TypeError for non-string input', () => {
  assert.throws(() => compareVersion(undefined, '1.0.0'), TypeError);
  assert.throws(() => compareVersion('1.0.0', null), TypeError);
  assert.throws(() => compareVersion(123, '1.0.0'), TypeError);
  assert.throws(() => compareVersion(['1', '0', '0'], '1.0.0'), TypeError);
});

test('throws TypeError for malformed strings', () => {
  const malformed = [
    '',
    '1',
    '1.2',
    '1.2.3.4',
    '1..3',
    '1.2.',
    '.1.2',
    '1,2,3',
    '1.2.a',
    '+1.2.3',
    '-1.2.3',
    ' 1.2.3',
    '1.2.3 ',
    '1.2.3\n',
    '1.2.3-beta',
    '1.2.3+build',
    '01.2.3',
    '1.02.3',
    '1.2.03',
    '00.0.0',
    '1.2.3١',
    '１.2.3',
  ];
  for (const bad of malformed) {
    assert.throws(() => compareVersion(bad, '1.0.0'), TypeError, `first arg: ${JSON.stringify(bad)}`);
    assert.throws(() => compareVersion('1.0.0', bad), TypeError, `second arg: ${JSON.stringify(bad)}`);
  }
});

test('validates both arguments even when the first decides the order', () => {
  assert.throws(() => compareVersion('0.0.0', 'x'), TypeError);
});

