class Emitter {
  #events = new Map();

  on(event, fn) {
    const registrations = this.#events.get(event) ?? [];
    this.#events.set(event, registrations);
    let registration = registrations.find((r) => r.fn === fn);
    if (!registration) {
      registration = { fn };
      registrations.push(registration);
    }
    // Unsubscribe targets this registration object, so a stale handle cannot remove a later re-registration.
    return () => this.#unregister(event, registration);
  }

  off(event, fn) {
    const registration = this.#events.get(event)?.find((r) => r.fn === fn);
    if (registration) this.#unregister(event, registration);
  }

  emit(event, value) {
    const registrations = this.#events.get(event);
    if (!registrations) return;
    for (const { fn } of [...registrations]) fn(value);
  }

  #unregister(event, registration) {
    const registrations = this.#events.get(event);
    if (!registrations) return;
    const index = registrations.indexOf(registration);
    if (index === -1) return;
    registrations.splice(index, 1);
    if (registrations.length === 0) this.#events.delete(event);
  }
}

