class Emitter {
  #listeners = new Map();

  on(event, fn) {
    if (typeof fn !== 'function') throw new TypeError('listener must be a function');
    const current = this.#listeners.get(event) ?? [];
    if (current.some((entry) => entry.fn === fn)) return () => {};

    const entry = { fn };
    this.#listeners.set(event, [...current, entry]);
    return () => this.#remove(event, entry);
  }

  off(event, fn) {
    const entry = (this.#listeners.get(event) ?? []).find((e) => e.fn === fn);
    if (entry) this.#remove(event, entry);
  }

  emit(event, value) {
    const current = this.#listeners.get(event);
    if (!current) return;
    for (const { fn } of current) fn(value);
  }

  #remove(event, entry) {
    const current = this.#listeners.get(event);
    if (!current || !current.includes(entry)) return;
    const next = current.filter((e) => e !== entry);
    if (next.length) this.#listeners.set(event, next);
    else this.#listeners.delete(event);
  }
}

module.exports = { Emitter };

