  assert.deepEqual(calls, [['first', 42], ['second', 42]]);
});

test('emit with no listeners is a no-op', () => {
  const emitter = new Emitter();
  assert.doesNotThrow(() => emitter.emit('missing', 1));
});

test('a listener is registered at most once per event', () => {
  const emitter = new Emitter();
