const noop = () => {};

class Emitter {
  #events = new Map();

  on(event, fn) {
    const entries = this.#entriesFor(event);
    if (entries.some((entry) => entry.fn === fn)) return noop;

    const entry = { fn };
    entries.push(entry);
    return () => this.#remove(event, entry);
  }

  off(event, fn) {
    const entry = this.#events.get(event)?.find((candidate) => candidate.fn === fn);
    if (entry) this.#remove(event, entry);
  }

  emit(event, value) {
    const entries = this.#events.get(event);
    if (!entries) return;

    for (const { fn } of entries.slice()) {
      fn(value);
    }
  }

  #entriesFor(event) {
    let entries = this.#events.get(event);
    if (!entries) {
      entries = [];
      this.#events.set(event, entries);
    }
    return entries;
  }

  #remove(event, entry) {
    const entries = this.#events.get(event);
    if (!entries) return;

    const index = entries.indexOf(entry);
    if (index !== -1) entries.splice(index, 1);
    if (entries.length === 0) this.#events.delete(event);
  }
}

