class Emitter {
  #listeners = new Map();

  on(event, fn) {
    const fns = this.#listeners.get(event) ?? [];
    if (!fns.includes(fn)) fns.push(fn);
    this.#listeners.set(event, fns);

    let subscribed = true;
    return () => {
      if (!subscribed) return;
      subscribed = false;
      this.off(event, fn);
    };
  }

  off(event, fn) {
    const fns = this.#listeners.get(event);
    if (!fns) return;
    const index = fns.indexOf(fn);
    if (index === -1) return;
    fns.splice(index, 1);
    if (fns.length === 0) this.#listeners.delete(event);
  }

  emit(event, value) {
    const fns = this.#listeners.get(event);
    if (!fns) return;
    for (const fn of fns.slice()) fn(value);
  }
}

