export type Result<T> = { ok: true; value: T } | { ok: false; error: string };

export function mapResult<T, U>(r: Result<T>, fn: (value: T) => U): Result<U> {
  if (r.ok) {
    return { ok: true, value: fn(r.value) };
  }
  return r;
}

export function unwrapOr<T>(r: Result<T>, fallback: T): T {
  return r.ok ? r.value : fallback;
}

import { test } from "node:test";
import assert from "node:assert/strict";
import { mapResult, unwrapOr, type Result } from "../src/solution.ts";

const parsed: Result<number> = { ok: true, value: 2 };
const failed: Result<number> = { ok: false, error: "bad input" };

test("mapResult applies fn to a success value", () => {
  const out = mapResult(parsed, (n) => n * 10);
  assert.deepEqual(out, { ok: true, value: 20 });
});

test("mapResult can change the value type", () => {
  const text: Result<string> = { ok: true, value: "hello" };
  const out = mapResult(text, (s) => s.length);
  assert.deepEqual(out, { ok: true, value: 5 });
});

test("mapResult does not call fn on failure", () => {
  let calls = 0;
  const out = mapResult(failed, (n) => {
    calls += 1;
    return n * 10;
  });
  assert.equal(calls, 0);
  assert.deepEqual(out, { ok: false, error: "bad input" });
});

test("mapResult returns a failure unchanged", () => {
  const out = mapResult(failed, (n) => n + 1);
  assert.equal(out, failed);
});

test("mapResult lets fn exceptions propagate", () => {
  assert.throws(
    () =>
      mapResult(parsed, () => {
        throw new Error("boom");
      }),
    { message: "boom" },
  );
});

test("unwrapOr returns the value on success", () => {
  assert.equal(unwrapOr(parsed, 0), 2);
});

test("unwrapOr returns the fallback on failure", () => {
  assert.equal(unwrapOr(failed, 0), 0);
});

test("mapResult and unwrapOr compose", () => {
  const scaled: number = unwrapOr(mapResult(parsed, (n) => n * 10), -1);
  assert.equal(scaled, 20);
});

