});

test("unwrapOr returns the fallback on failure", () => {
  assert.equal(unwrapOr(fail<number>("nope"), 0), 0);
});

test("unwrapOr composes with mapResult", () => {
  const value = unwrapOr(mapResult(parseInteger("21"), (n) => n * 2), -1);
  const fallback = unwrapOr(mapResult(parseInteger("x"), (n) => n * 2), -1);
  assert.equal(value, 42);
  assert.equal(fallback, -1);
});

